sp_widget.client_script:
function($scope, $rootScope, $timeout) {
    // Variável do gráfico renomeada
    var chartDespPessoal = null;

    // Escopo renomeado
    $scope.anoSelecionadoDespPessoal = "";
    $scope.exibirGraficoDespPessoal = false;

    var coresDespPessoal = {
        apurado: '#a7b9e8',
        meta: '#4b77bf'
    };

    /**
     * Função para carregar os dados do servidor com filtro de ano
     */
    function carregarDadosDespPessoalFiltrado() {
        var filtros = {
            ano: $scope.anoSelecionadoDespPessoal || ""
        };
        $scope.server.get(filtros).then(function(response) {
            // Lendo a nova variável de dados vinda do Server Script
            var dados = response.data.dadosGraficoDespPessoal || [];
            var anosDisponiveis = response.data.anos || [];

            $timeout(function() {
                montarGraficoDespPessoal(dados, anosDisponiveis);
            });
        });
    }

    // O evento 'anoSelecionado' geralmente vem de um filtro global. 
    // Mantive o nome do evento igual, mas a ação interna é isolada.
    $rootScope.$on('anoSelecionado', function(event, ano) {
        $scope.anoSelecionadoDespPessoal = ano;
        carregarDadosDespPessoalFiltrado();
    });

    // Chamada inicial
    carregarDadosDespPessoalFiltrado();

    function montarGraficoDespPessoal(listaDados, anosDisponiveis) {

        var anosPresentes = [];
        listaDados.forEach(function(item) {
            if (anosPresentes.indexOf(item.ano) === -1) {
                anosPresentes.push(item.ano);
            }
        });

        anosPresentes.sort(function(a, b) {
            return parseInt(a) - parseInt(b);
        });

        // Lógica de destruição/limpeza usando as novas variáveis
        if (anosPresentes.length === 0) {
            if (chartDespPessoal) {
                chartDespPessoal.destroy();
                chartDespPessoal = null;
            }
            $scope.exibirGraficoDespPessoal = false;
            return;
        }
        $scope.exibirGraficoDespPessoal = true;

        var dadosApurado = anosPresentes.map(function(ano) {
            var item = listaDados.find(function(d) { return d.ano === ano; });
            return item ? parseFloat(item.apurado) : null;
        });
        var dadosMeta = anosPresentes.map(function(ano) {
            var item = listaDados.find(function(d) { return d.ano === ano; });
            return item ? parseFloat(item.meta) : null;
        });
        var desiredType = (anosPresentes.length === 1) ? 'bar' : 'line';

        var datasets = [{
            label: 'Valor Apurado',
            data: dadosApurado,
            fill: false,
            tension: 0.1
        }, {
            label: 'Meta',
            data: dadosMeta,
            fill: false,
            tension: 0.1
        }];

        if (desiredType === 'line') {
            datasets[0].borderColor = coresDespPessoal.apurado;
            datasets[0].backgroundColor = coresDespPessoal.apurado;
            datasets[0].borderWidth = 4;
            datasets[0].pointStyle = 'circle';
            datasets[0].pointRadius = 10;

            datasets[1].borderColor = coresDespPessoal.meta;
            datasets[1].backgroundColor = coresDespPessoal.meta;
            datasets[1].borderWidth = 4;
            datasets[1].pointStyle = 'circle';
            datasets[1].pointRadius = 10;
        } else { // bar
            datasets[0].backgroundColor = coresDespPessoal.apurado;
            datasets[0].borderColor = coresDespPessoal.apurado;
            datasets[0].borderWidth = 1;

            datasets[1].backgroundColor = coresDespPessoal.meta;
            datasets[1].borderColor = coresDespPessoal.meta;
            datasets[1].borderWidth = 1;
        }

        datasets[0].pointStyle = 'rect';
        datasets[0].pointBackgroundColor = coresDespPessoal.apurado;
        datasets[0].pointBorderColor = coresDespPessoal.apurado;
        datasets[0].pointBorderWidth = 0;

        datasets[1].pointStyle = 'rect';
        datasets[1].pointBackgroundColor = coresDespPessoal.meta;
        datasets[1].pointBorderColor = coresDespPessoal.meta;
        datasets[1].pointBorderWidth = 0;

        // ATENÇÃO: Pegando o novo ID do canvas
        var ctx = document.getElementById('graficoDespPessoalLinha').getContext('2d');

        if (chartDespPessoal) {
            if (chartDespPessoal.config.type !== desiredType) {
                chartDespPessoal.destroy();
                chartDespPessoal = null;
            } else {
                chartDespPessoal.data.labels = anosPresentes;
                chartDespPessoal.data.datasets[0].data = dadosApurado;
                chartDespPessoal.data.datasets[1].data = dadosMeta;
                chartDespPessoal.update();
                return;
            }
        }

        chartDespPessoal = new Chart(ctx, {
            type: desiredType,
            data: {
                labels: anosPresentes,
                datasets: datasets
            },
            options: {
                responsive: true,
                maintainAspectRatio: false,
                animation: {
                    duration: 700,
                    easing: 'easeInOutQuad'
                },
                scales: {
                    x: {
                        display: true,
                        title: { display: false },
                        offset: true,
                        grid: { offset: true },
                        ticks: {
                            color: '#0E2B69',
                            font: {
                                size: 16,
                                weight: 800,
                                family: 'Roboto Flex, sans-serif',
                                lineHeight: 1.8
                            },
                            padding: 6,
                            maxRotation: 0,
                            autoSkip: false
                        }
                    },
                    y: {
                        display: true,
                        position: 'right',
                        min: 0,
                        max: 100,
                        ticks: {
                            callback: function(value) {
                                return value.toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 }) + '%';
                            },
                            color: '#0E2B69',
                            font: {
                                size: 14,
                                family: 'Roboto Flex, sans-serif'
                            }
                        }
                    }
                },
                plugins: {
                    legend: {
                        display: true,
                        position: 'top',
                        labels: { usePointStyle: true }
                    },
                    tooltip: {
                        enabled: true,
                        callbacks: {
                            label: function(context) {
                                return context.dataset.label + ': ' + context.raw.toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 }) + '%';
                            }
                        }
                    },
                    datalabels: {
                        anchor: 'end',
                        align: 'top',
                        formatter: function(value) {
                            if (value === null) return '';
                            return value.toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 }) + '%';
                        },
                        color: '#000',
                        font: { weight: 'bold' }
                    }
                }
            }
        });
    }
}

sp_widget.css:
canvas {
  display: block;
  margin: 0 auto;
}

h3, div, span {
 font-family: 'Roboto Flex', sans-serif;
}

.titleDespPessoal{
   font-family: Roboto;
  font-weight: 500;
  font-style: Medium;
  font-size: 24px;
  leading-trim: NONE;
  line-height: 100%;
  letter-spacing: 0%;
	color:#021770;
}

/* --- Media Queries para Responsividade --- */

/* Telas Pequenas (Mobile S, M, L - até 767px) */
@media (max-width: 767px) {
  canvas {
    max-width: 90%; /* Ajustar a largura máxima do canvas */
  }
  h3 {
    font-size: 1rem; /* Ajustar o tamanho da fonte do título */
  }
}

/* Tablets (iPad Mini, iPad Air, Surface Duo, Galaxy Z Fold 5 - 768px até 1023px) */
@media (min-width: 768px) and (max-width: 1023px) {
  canvas {
    max-width: 80%;
  }
  h3 {
    font-size: 1.1rem;
  }
}

/* Laptops e Telas Maiores (iPad Pro, Surface Pro 7, Laptops, 4K - 1024px em diante) */
@media (min-width: 1024px) {
  canvas {
    max-width: none;
  }
  h3 {
  }
}

/* Ajustes para o Surface Duo (540x720) */
@media (width: 540px) and (height: 720px) {
    canvas {
        max-width: 95%;
    }
}

/* Ajustes para Galaxy Z Fold 5 (max-width: 350px) */
@media (max-width: 350px) {
    h3 {
        font-size: 0.9rem;
    }
}

sp_widget.script:
(function() {
    input = input || {};
    // Variável de dados renomeada para isolamento
    data.dadosGraficoDespPessoal = [];
    data.anos = [];

    var anoFiltro = input.ano || "";

    // --- 1. Busca e Popula os Anos Disponíveis ---
    var grAnos = new GlideAggregate('x_sded9_portal_t_0_programa_de_ajuste_fiscal');
    grAnos.addAggregate('COUNT');
    grAnos.groupBy('u_ano');
    grAnos.orderBy('u_ano');
    grAnos.query();

    while (grAnos.next()) {
        data.anos.push(grAnos.getValue('u_ano').toString());
    }
    data.anos = Array.from(new Set(data.anos));
    data.anos.sort();

    // --- 2. Busca os Dados de Despesa Pessoal ---
    var grDespPessoal = new GlideRecord('x_sded9_portal_t_0_programa_de_ajuste_fiscal');

    if (anoFiltro !== "" && anoFiltro.toLowerCase() !== "todos") {
        grDespPessoal.addQuery('u_ano', anoFiltro);
    }

    grDespPessoal.orderBy('u_ano');
    grDespPessoal.query();

    var listaDespPessoal = [];
    while (grDespPessoal.next()) {
        var ano = grDespPessoal.getValue('u_ano').toString();
        // Campos mantidos conforme seu original, pois já referenciam despesa com pessoal
        var apurado = grDespPessoal.getValue('valor_apurado_despesa_com_pessoal') || '0';
        var meta = grDespPessoal.getValue('meta_despesa_com_pessoal') || '0';

        listaDespPessoal.push({
            ano: ano,
            apurado: apurado,
            meta: meta
        });
    }

    data.dadosGraficoDespPessoal = listaDespPessoal;
})();
